import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.DaGSOal_.js";const h=JSON.parse('{"title":"Deblx Documentation","description":"Setup guides and product documentation for Deblx Unreal Engine plugins.","frontmatter":{"title":"Deblx Documentation","description":"Setup guides and product documentation for Deblx Unreal Engine plugins."},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1794006476000}'),r={name:"index.md"};function n(s,e,l,c,d,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="deblx-documentation" tabindex="-1">Deblx Documentation <a class="header-anchor" href="#deblx-documentation" aria-label="Permalink to &quot;Deblx Documentation&quot;">​</a></h1><p>Welcome to the documentation for Unreal Engine <strong>5.1+</strong> plugins by Deblx. Browse installation guides, features, practical workflows and common issue solutions.</p><div class="info custom-block"><p class="custom-block-title">Getting Started</p><p>New here? <a href="/getting-started">Choose a Plugin</a> or select a product from the navigation on the left. For updates, visit the <a href="https://changelog.deblx.com" target="_blank" rel="noreferrer">Deblx Changelog</a>.</p></div><h2 id="plugin-documentation" tabindex="-1">Plugin Documentation <a class="header-anchor" href="#plugin-documentation" aria-label="Permalink to &quot;Plugin Documentation&quot;">​</a></h2><h3 id="loading-screen-pro" tabindex="-1">Loading Screen Pro <a class="header-anchor" href="#loading-screen-pro" aria-label="Permalink to &quot;Loading Screen Pro&quot;">​</a></h3><p>Create cinematic loading screens with slideshows, progress indicators, tips, music and configurable transitions. Basic setup uses a Data Asset without C++.</p><p><a href="/loading-screen-pro/">Overview</a> · <a href="/loading-screen-pro/installation">Installation</a> · <a href="/loading-screen-pro/usage">Usage</a></p><h3 id="quick-notes-todo" tabindex="-1">Quick Notes / ToDo <a class="header-anchor" href="#quick-notes-todo" aria-label="Permalink to &quot;Quick Notes / ToDo&quot;">​</a></h3><p>Track TODOs, bug markers and reminders in your viewport and Blueprint Editor with a centralized overview panel.</p><p><a href="/quick-notes/">Overview</a> · <a href="/quick-notes/installation">Installation</a> · <a href="/quick-notes/usage">Usage</a></p><h3 id="duplicate-asset-detector-pro" tabindex="-1">Duplicate Asset Detector Pro <a class="header-anchor" href="#duplicate-asset-detector-pro" aria-label="Permalink to &quot;Duplicate Asset Detector Pro&quot;">​</a></h3><p>Identify duplicate content, inspect dependencies and review cleanup operations before removing redundant assets.</p><p><a href="/duplicate-asset-detector/">Overview</a> · <a href="/duplicate-asset-detector/installation">Installation</a> · <a href="/duplicate-asset-detector/usage">Usage</a></p><h3 id="asset-size-analyzer" tabindex="-1">Asset Size Analyzer <a class="header-anchor" href="#asset-size-analyzer" aria-label="Permalink to &quot;Asset Size Analyzer&quot;">​</a></h3><p>Inspect asset disk size and estimated runtime memory usage, filter results and export reports to CSV.</p><p><a href="/asset-size-analyzer/">Overview</a> · <a href="/asset-size-analyzer/installation">Installation</a> · <a href="/asset-size-analyzer/usage">Usage</a></p><h2 id="how-to-begin" tabindex="-1">How to Begin <a class="header-anchor" href="#how-to-begin" aria-label="Permalink to &quot;How to Begin&quot;">​</a></h2><ol><li><a href="/getting-started">Choose the right plugin</a> for your task.</li><li>Check <a href="/compatibility">engine compatibility</a> and install the tool through <a href="https://www.fab.com/de/sellers/Deblx" target="_blank" rel="noreferrer">Fab</a>.</li><li>Follow the corresponding installation and usage guides.</li><li>Check the troubleshooting or FAQ section if something is unclear.</li></ol><h2 id="more-resources" tabindex="-1">More Resources <a class="header-anchor" href="#more-resources" aria-label="Permalink to &quot;More Resources&quot;">​</a></h2><ul><li><a href="/support">Support &amp; Feedback</a> — ask questions, suggest improvements or report issues.</li><li><a href="/verification">Discord Verification</a> — product verification instructions.</li><li><a href="https://changelog.deblx.com" target="_blank" rel="noreferrer">Deblx Changelog</a> — release notes and maintenance updates.</li><li><a href="https://discord-dev.deblx.com" target="_blank" rel="noreferrer">Deblx Developer Discord</a> — developer discussions.</li></ul><div class="tip custom-block"><p class="custom-block-title">Improve this documentation</p><p>Every article includes an <strong>Edit this page on GitHub</strong> link. Contributions can be proposed through the <a href="https://github.com/deblx/docs" target="_blank" rel="noreferrer">documentation repository</a>.</p></div>',21)])])}const g=a(r,[["render",n]]);export{h as __pageData,g as default};
